  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "La résolution 250, page 8, autorise la mainlevée de l’hypothèque et la renonciation au droit de préemption prévus à l’acte publié sous le numéro 28 261 535."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "L’avis de motion du règlement 1571-08-2026 est expressément donné page 10 et constitue une unité distincte du projet de règlement."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La résolution 256 adopte expressément le projet de règlement 1571-08-2026 à la page 11, sans constituer l’adoption définitive du règlement."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La page 11 atteste l’avis de motion du règlement de zonage 1841-53-2026 concernant notamment les zones Rc-23, Cbb-1 et Ib-1."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 258, page 12, adopte le premier projet de règlement de zonage 1841-53-2026, distinct de son avis de motion."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "L’avis de motion du règlement de lotissement 1842-06-2026 figure bien page 12 sous le numéro 259-05-2026."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 260, page 13, adopte expressément le projet de règlement de lotissement 1842-06-2026."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La résolution 262 approuve la dérogation mineure 2026-006 au 518 rue Principale dès la page 14, avec des conditions détaillées aux pages 14 et 15."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La résolution 263, page 15, approuve la dérogation mineure 2026-034 au 111 rue du Muscadet concernant la superficie des bâtiments accessoires."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le dispositif de la résolution 264, page 16, approuve sous conditions le PIIA 2026-003 au 518 rue Principale pour l’affichage et les aménagements du service au volant."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "La résolution 265, page 16, approuve le PIIA 2025-087 au 1529 rue du Sud pour l’installation d’affichage et des travaux de peinture."
    },
    {
      "item": "i12",
      "choice": "v1",
      "reason": "La résolution 266, page 17, refuse expressément le PIIA 2026-029 pour un garage au 295 rue d’Ontario, conformément à la règle voulant que les refus restent des refus."
    },
    {
      "item": "i13",
      "choice": "v1",
      "reason": "La résolution 267, page 17, approuve explicitement le PIIA 2026-043 parmi les deux demandes nommées au 1600 rue du Sud."
    },
    {
      "item": "i14",
      "choice": "v1",
      "reason": "Le PIIA 2026-047 est explicitement nommé et approuvé page 17 avec le PIIA 2026-043, ce qui justifie une unité distincte malgré leur résolution commune."
    },
    {
      "item": "i15",
      "choice": "v1",
      "reason": "La résolution 268, page 18, approuve sous conditions le PIIA 2026-040 pour une nouvelle enseigne au 101 rue Albert, local 1002."
    },
    {
      "item": "i16",
      "choice": "v1",
      "reason": "La résolution 269, page 18, approuve le PIIA 2026-013 pour une réfection majeure et un agrandissement de la résidence au 454 rue Principale."
    },
    {
      "item": "i17",
      "choice": "v1",
      "reason": "La résolution 270 approuve page 18 le PIIA 2026-042 pour le retrait de la marquise au 419 rue de la Rivière."
    },
    {
      "item": "i18",
      "choice": "v1",
      "reason": "La résolution 271, page 19, approuve le PIIA 2026-039 modifiant le projet résidentiel Le Nordik aux 141 à 153 rue du Nord."
    },
    {
      "item": "i19",
      "choice": "v1",
      "reason": "La résolution 272, page 19, approuve le PIIA 2026-041 pour une enseigne au-dessus de l’entrée principale du 111 rue William."
    },
    {
      "item": "i20",
      "choice": "v1",
      "reason": "La résolution 273, page 20, approuve sous conditions le PIIA 2026-044 au 191 rue Pauline-Julien, notamment avec un toit à deux pentes uniquement."
    },
    {
      "item": "i21",
      "choice": "v1",
      "reason": "La résolution 274, page 20, approuve le PIIA 2026-045 pour un bâtiment accessoire de 10 x 12 pieds sans appentis, sous condition d’un seul matériau de revêtement extérieur."
    },
    {
      "item": "i22",
      "choice": "v1",
      "reason": "La résolution 275, page 21, approuve sous conditions le PIIA 2026-046 pour transformer une partie de la terrasse du 82 rue Pine en véranda quatre saisons."
    },
    {
      "item": "i23",
      "choice": "v1",
      "reason": "La résolution 276 approuve page 21 le PIIA 2026-051 pour des enclos à bacs sur les rues Pauline-Julien et Albert-Millaire, avec des conditions poursuivies page 22."
    },
    {
      "item": "i24",
      "choice": "v1",
      "reason": "La résolution 277, page 22, refuse le PIIA 2026-035 pour un immeuble de neuf logements à l’angle des rues Bernard et du Nord sur le lot 3 356 557."
    },
    {
      "item": "i25",
      "choice": "v1",
      "reason": "Le dispositif de la résolution 278, page 22, refuse explicitement la modification du PIIA 2025-120 concernant les deux propriétés de la rue Paul-Hébert."
    },
    {
      "item": "i26",
      "choice": "v1",
      "reason": "La résolution 279, page 23, approuve une modification actuelle du PIIA 2025-117 au 1447 rue du Sud, et non un simple rappel de la demande initiale."
    },
    {
      "item": "i27",
      "choice": "v1",
      "reason": "La résolution 280, dont l’intitulé cité et le début du dispositif figurent page 23, approuve le rendu architectural CDEMO 2025-116 pour le projet de remplacement au 1037-1041 rue Principale."
    },
    {
      "item": "i28",
      "choice": "v1",
      "reason": "La résolution 282, page 25, exige une contribution pour parcs de 14 500 $ avant l’autorisation de délivrance du permis de lotissement visant le lot projeté 6 725 842."
    },
    {
      "item": "i29",
      "choice": "v1",
      "reason": "La résolution 283, page 25, autorise actuellement la signature de l’acte de rétrocession du lot 4 621 525 à la Ville, indépendamment des décisions historiques rappelées."
    },
    {
      "item": "i30",
      "choice": "v1",
      "reason": "La résolution 285, page 27, entérine l’avenant 1 au protocole d’infrastructures du développement Village-École et autorise sa signature avec Village Scolaire inc."
    },
    {
      "item": "i31",
      "choice": "v1",
      "reason": "La résolution 291, page 31, autorise une dépense comprenant explicitement l’acquisition de servitudes derrière les propriétés de la rue Jules-Monast, acte foncier distinct des travaux de drainage."
    },
    {
      "item": "i32",
      "choice": "v1",
      "reason": "La résolution 298, page 34, autorise le bail de location de la cantine pour la saison 2026, acte foncier non résidentiel sans étape réglementaire spécifique."
    },
    {
      "item": "i33",
      "choice": "v1",
      "reason": "L’intitulé cité figure page 34 et la résolution 299 poursuivie page 35 autorise ce bail immobilier d’un an à compter du 1er mai 2026, inclus parmi les actes fonciers non résidentiels."
    },
    {
      "item": "i34",
      "choice": "v1",
      "reason": "La résolution 315, page 42, adopte expressément le second projet de PPCMOI 2026-032 pour quatre logements touristiques au total et la régularisation du stationnement au 245 rue Principale."
    }
  ]
}
